import urllib.request, json

# Try to get SPY price
urls = {
    'SPY': 'https://query1.finance.yahoo.com/v8/finance/chart/SPY?range=1d&interval=1d',
    'QQQ': 'https://query1.finance.yahoo.com/v8/finance/chart/QQQ?range=1d&interval=1d',
    'VIX': 'https://query1.finance.yahoo.com/v8/finance/chart/^VIX?range=1d&interval=1d',
}

for name, url in urls.items():
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        resp = urllib.request.urlopen(req, timeout=10)
        data = json.loads(resp.read())
        result = data['chart']['result'][0]
        meta = result['meta']
        if 'regularMarketPrice' in meta:
            price = meta['regularMarketPrice']
        elif 'previousClose' in meta:
            price = meta['previousClose']
        else:
            price = 'N/A'
        print(f'{name}: \${price}')
        if 'chartPreviousClose' in meta:
            print(f'  Prev close: \${meta[\"chartPreviousClose\"]}')
    except Exception as e:
        print(f'{name}: Error - {e}')
"
